#include <iostream>
#include <vector>
#include <string>
#include <utility>
#include <algorithm>
#include <ranges>
using namespace std;

int main() {
    array<int, 5> point{};
    for (auto&& p : point)
        cin >> p;

    // すべての参加者の得点と名前の情報
    vector<pair<int, string>> standings;
    for (int bit = 1; bit < 32; ++bit) {
        int solved_point = 0;
        string name = "";
        for (int digit = 0; digit < 5; ++digit)
            // digit 桁めのビットが立っているのが digit 問目を解いた人
            if (bit & 1 << digit) {
                // 得点と名前にその問題を追加
                solved_point += point[digit];
                name += "ABCDE"[digit];
            }
        // 得点と名前の情報を追加
        standings.emplace_back(solved_point, name);
    }

    // 名前の昇順にソート
    ranges::sort(standings, less{}, &pair<int, string>::second);
    // 得点の降順に安定ソート
    ranges::stable_sort(standings, greater{}, &pair<int, string>::first);

    // 名前を順に出力
    for (const auto& name : standings | views::values)
        cout << name << endl;

    return 0;
}
